-- Corrections du quiz de fin de semaine : vie_marine.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

UPDATE game_cards SET related_objective_id = '58', data = '{"question":"Comment les espèces marines sont-elles adaptées à l''estran, un milieu extrême ?","answers":["Elles ne s''y adaptent pas — c''est un milieu hostile vide de vie","Elles développent des adaptations spécifiques : carapaces, adhérence, dessèchement toléré","Elles migrent à chaque marée","Elles vivent uniquement dans l''eau constamment"],"correctAnswerIndex":1,"explanation":"L''estran alterne immersion et émersion, chaleur et froid. Ses habitants ont des adaptations remarquables : la patelle colle à son rocher, les algues sont flexibles.","version_enfant":{"question":"Comment les animaux de l''estran font-ils pour survivre là où l''eau part et revient sans arrêt ?","answers":["Ils ne survivent pas vraiment","Chacun a sa solution : carapace, ventouse, coquille qui se ferme","Ils partent tous à marée basse","Ils vivent uniquement dans l''eau"],"correctAnswerIndex":1,"explanation":"Chaque espèce a trouvé sa solution : carapace contre le sec, ventouse contre les vagues, souplesse pour plier."}}'::jsonb WHERE id = '480e8b7e-ccaf-4b5d-bad0-4f97f7fac8b5';
UPDATE game_cards SET related_objective_id = '59', data = '{"question":"Comment fonctionne une chaîne alimentaire marine ?","answers":["Les gros poissons mangent les petits, sans autre lien","Du phytoplancton aux grands prédateurs, chaque maillon est essentiel","Les algues mangent les poissons","Seuls les animaux du fond y participent"],"correctAnswerIndex":1,"explanation":"Phytoplancton, zooplancton, petits poissons, grands prédateurs : chaque maillon est vital. La disparition d''un maillon se répercute dans toute la chaîne.","version_enfant":{"question":"Qui est tout en bas de la chaîne alimentaire de la mer ?","answers":["Les gros poissons","Une toute petite algue qu''on ne voit presque pas","Les crabes","Les oiseaux"],"correctAnswerIndex":1,"explanation":"Tout commence par le plancton, invisible, qui capte l''énergie du soleil. Sans lui, plus rien ne mange."}}'::jsonb WHERE id = 'e5ab5f68-6bee-4a0b-9bf7-b02f17867870';
